using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        foreach (Object o in Selection.objects)
            result.Log("SELECTED: " + o.GetType().Name + " @ " + AssetDatabase.GetAssetPath(o));

        foreach (string t in new[] { "UniversalRenderPipelineAsset", "UniversalRendererData", "UniversalRenderPipelineGlobalSettings", "Renderer2DData" })
            foreach (string g in AssetDatabase.FindAssets("t:" + t))
                result.Log("FOUND " + t + ": " + AssetDatabase.GUIDToAssetPath(g));

        result.Log("Graphics default RP: " + AssetDatabase.GetAssetPath(GraphicsSettings.defaultRenderPipeline));
        string[] names = QualitySettings.names;
        for (int i = 0; i < names.Length; i++)
        {
            RenderPipelineAsset rp = QualitySettings.GetRenderPipelineAssetAt(i);
            result.Log("Quality[" + i + "] " + names[i] + " → " + (rp != null ? AssetDatabase.GetAssetPath(rp) : "(none = ใช้ default)"));
        }
        result.Log("Current quality: " + QualitySettings.GetQualityLevel());

        foreach (string g in AssetDatabase.FindAssets("t:UniversalRenderPipelineAsset"))
        {
            var a = AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(AssetDatabase.GUIDToAssetPath(g));
            var so = new SerializedObject(a);
            var list = so.FindProperty("m_RendererDataList");
            for (int i = 0; i < list.arraySize; i++)
            {
                var r = list.GetArrayElementAtIndex(i).objectReferenceValue;
                result.Log("  " + a.name + " renderer[" + i + "] = " + (r != null ? AssetDatabase.GetAssetPath(r) : "null"));
            }
        }
        var gs = GraphicsSettings.GetSettingsForRenderPipeline<UniversalRenderPipeline>();
        result.Log("Registered URP Global Settings: " + (gs != null ? AssetDatabase.GetAssetPath(gs) : "none"));
    }
}

