using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
using System.Collections.Generic;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string[] unused =
        {
            "Assets/Scenes/Base/Global Volume Profile.asset",
            "Assets/Scenes/HideOut/Global Volume Profile.asset",
            "Assets/Scenes/TestingGround/Sky and Fog Volume Profile 1.asset",
            "Assets/Scenes/TestingGround/Sky and Fog Volume Profile.asset",
            "Assets/TextMesh Pro/Examples & Extras/Scenes/28 - HDRP Shader Example/Sky and Fog Volume Profile.asset",
        };
        // ตรวจซ้ำด้วย Dependencies ของทุก Scene ก่อนลบ
        HashSet<string> used = new HashSet<string>();
        foreach (string g in AssetDatabase.FindAssets("t:Scene"))
            foreach (string d in AssetDatabase.GetDependencies(AssetDatabase.GUIDToAssetPath(g), false)) used.Add(d);
        foreach (string g in AssetDatabase.FindAssets("t:Prefab"))
            foreach (string d in AssetDatabase.GetDependencies(AssetDatabase.GUIDToAssetPath(g), false)) used.Add(d);

        foreach (string p in unused)
        {
            if (used.Contains(p)) { result.LogWarning("ยังมีการใช้ ข้าม: " + p); continue; }
            bool ok = AssetDatabase.MoveAssetToTrash(p);
            result.Log((ok ? "ย้ายลงถังขยะ: " : "ลบไม่ได้: ") + p);
        }

        // ---------- ตั้งลุค PS1Signalis (ค่าเดียวกับ Shader เดิม) + Distort นิดๆ
        VolumeProfile profile = AssetDatabase.LoadAssetAtPath<VolumeProfile>("Assets/DefaultVolumeProfile.asset");
        profile.TryGet(out ParalateScreenFx fx);
        fx.ps1Enabled.value = true;
        fx.pixelHeight.value = 240;
        fx.colorLevels.value = 16;
        fx.dither.value = 0.6f;
        fx.saturation.value = 0.75f;
        fx.contrast.value = 1.1f;
        fx.tint.value = new Color(0.85f, 0.95f, 1f, 1f);
        fx.chromaticAberration.value = 0.006f;
        fx.grainIntensity.value = 0.06f;
        fx.grainSize.value = 4f;          // เดิมเม็ดเท่าพิกเซล 240p ≈ 4.5 พิกเซลจอที่ 1080p
        fx.scanline.value = 0.18f;
        fx.vignette.value = 0.5f;
        EditorUtility.SetDirty(fx);
        EditorUtility.SetDirty(profile);
        AssetDatabase.SaveAssets();
        result.Log("ตั้งลุค PS1Signalis แล้ว");
    }
}

