using UnityEngine;
using UnityEditor;
using UnityEditor.Rendering;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        AssetDatabase.ImportAsset("Assets/ArtAssets/Shader/PSXLit.shader", ImportAssetOptions.ForceUpdate);
        AssetDatabase.Refresh();
        Shader s = AssetDatabase.LoadAssetAtPath<Shader>("Assets/ArtAssets/Shader/PSXLit.shader");
        result.Log("shader=" + (s != null ? s.name : "null") + " supported=" + (s != null && s.isSupported) + " passes=" + (s != null ? s.passCount : 0));

        string matPath = "Assets/ArtAssets/Material/PSX_Example.mat";
        Material m = AssetDatabase.LoadAssetAtPath<Material>(matPath);
        if (m == null)
        {
            m = new Material(s);
            AssetDatabase.CreateAsset(m, matPath);
        }
        for (int i = 0; i < s.passCount; i++)
            ShaderUtil.CompilePass(m, i, true);

        foreach (ShaderMessage msg in ShaderUtil.GetShaderMessages(s))
            result.Log("[" + msg.severity + "] line " + msg.line + " " + msg.message + " (" + msg.platform + ")");
        result.Log("hasError=" + ShaderUtil.ShaderHasError(s));
        AssetDatabase.SaveAssets();
    }
}

