using UnityEngine;
using UnityEditor;
using UnityEditor.Rendering;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        Shader s = Shader.Find("Paralate/PSX Lit");
        string[][] sets =
        {
            new[] { "_MAIN_LIGHT_SHADOWS_CASCADE", "_ADDITIONAL_LIGHTS", "FOG_LINEAR" },
            new[] { "_MAIN_LIGHT_SHADOWS", "_ADDITIONAL_LIGHTS_VERTEX", "FOG_EXP2", "_ALPHATEST_ON" },
            new[] { "_PSX_UNLIT", "_ALPHATEST_ON", "_CASTING_PUNCTUAL_LIGHT_SHADOW" },
        };
        foreach (string[] set in sets)
        {
            Material m = new Material(s);
            foreach (string k in set) m.EnableKeyword(k);
            for (int i = 0; i < s.passCount; i++) ShaderUtil.CompilePass(m, i, true);
            Object.DestroyImmediate(m);
        }
        int n = 0;
        foreach (ShaderMessage msg in ShaderUtil.GetShaderMessages(s))
        { n++; result.Log("[" + msg.severity + "] line " + msg.line + " " + msg.message); }
        result.Log("messages=" + n + " hasError=" + ShaderUtil.ShaderHasError(s));
    }
}

